"""Write LaTeX tables and number macros for the paper from the local data: python -m src.make_tables"""
from pathlib import Path

from . import config as C
from .data import ROOT, descriptives, load_log_returns, yearly_table


def main(out=ROOT / "paper" / "tables" / "data_summary.tex"):
    lr = load_log_returns()
    yt = yearly_table(lr)
    ds = descriptives(lr)
    lines = [
        "% generated by src/make_tables.py; do not edit",
        rf"\newcommand{{\nDays}}{{{len(lr):,}}}".replace(",", "{,}"),
        rf"\newcommand{{\dataStart}}{{{lr.index[0]:%-d %B %Y}}}",
        rf"\newcommand{{\dataEnd}}{{{lr.index[-1]:%-d %B %Y}}}",
        r"\newcommand{\yearlyTable}{%",
        r"\begin{tabular}{lrrrrr}",
        r"\toprule",
        r"Year & Days & Account & SPY & BND & GLD \\",
        r"\midrule",
    ]
    for y, r in yt.iterrows():
        lines.append(f"{y} & {int(r.days)} & " + " & ".join(f"{r['vol_' + a]:.2f}" for a in C.ASSETS) + r" \\")
    lines += [r"\midrule",
              f"All & {len(lr)} & " + " & ".join(f"{ds.loc[a, 'vol_ann']:.2f}" for a in C.ASSETS) + r" \\",
              r"\bottomrule", r"\end{tabular}}"]
    Path(out).write_text("\n".join(lines) + "\n")
    print("wrote", out)


if __name__ == "__main__":
    main()
